```c++
int main(){

	int x;
	x = 100;
	cout << "Before update: " 
		<< x << endl;
	update_x(x);
	
	cout << "After update: "
		<< x << endl;
	return 0;
}

void update_x(int x){

	x += 10;
	cout << "Inside update: "
		<< x << endl;
	return;
}

int swap(int a, int b){
	int temp;
	temp = a;
	a = b;
	b = temp;
	return b;
	// This wont swap in the main
	
}
```

```c++
int a; ->
int& a;

int main() {
	int a = 20, b = 30
	cout << "Before swap: " << a << b;
	swap(a,b);
	cout << "After swap: " << a << b;
	return 0;
}
void swap(int& a, int& b){
	/* Swapping memory location rather
	than the variable */

	int temp;
	temp = a
	a = b;
	b = temp;
	return;
}
```
